mapper.delete:
DELETE FROM counter_reaction
WHERE entity_type = #{entityType}
  AND entity_id = #{entityId}
  AND metric = #{metric}
  AND user_id = #{userId}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM counter_reaction
    WHERE entity_type = #{entityType}
      AND entity_id = #{entityId}
      AND metric = #{metric}
      AND user_id = #{userId}
)

SELECT entity_id
FROM counter_reaction
WHERE entity_type = #{entityType}
  AND metric = #{metric}
  AND user_id = #{userId}
  AND entity_id IN

    #{entityId}

SELECT user_id
FROM counter_reaction
WHERE entity_type = #{entityType}
  AND entity_id = #{entityId}
  AND metric = #{metric}
  AND user_id > #{afterUserId}
ORDER BY user_id
LIMIT #{limit}

SELECT COUNT(*)
FROM counter_reaction
WHERE entity_type = #{entityType}
  AND entity_id = #{entityId}
  AND metric = #{metric}
